/**
 * output-guard must not strip output CC actually reads.
 *
 * The guard held two HAND-TYPED allow-lists whose provenance comment cited
 * "types.ts plus the #1234 audit" — one hand-maintained artifact plus a memory.
 * Both were wrong. CC's shipped binary documents Stop, SubagentStop and
 * PostToolBatch as additionalContext consumers, verbatim:
 *
 *   "Hook-specific output for the Stop event. additionalContext is non-error
 *    feedback delivered to the model; the conversation continues so the model
 *    can act on it."
 *   "Hook-specific output for the SubagentStop event. additionalContext is
 *    non-error feedback delivered to the subagent..."
 *   "Return additionalContext via hookSpecificOutput to inject context once
 *    for the whole batch."                                    [PostToolBatch]
 *
 * The guard named none of them, so it silently DELETED additionalContext from
 * six live hooks: stop/task-completion-check, stop/stop-failure-handler,
 * stop/session-summary, subagent-stop/sync-subagent-stop-dispatcher,
 * subagent-stop/subagent-scope-auditor, subagent-stop/retry-handler.
 *
 * A guard that wrongly ALLOWS gets caught — something misbehaves. A guard that
 * wrongly STRIPS produces silence. That is the direction nobody checks, so it
 * is the direction this file checks.
 *
 * Every case below FAILS against the pre-2026-08-08 allow-lists.
 */
import { describe, it, expect } from 'vitest';
import { sanitizeOutput } from '../../bin/output-guard.mjs';
import {
  EVENTS_WITH_ADDITIONAL_CONTEXT,
  EVENTS_WITH_HOOK_EVENT_NAME,
  UNVERIFIED_KEYS,
} from '../../bin/cc-output-keys.generated.mjs';

/** What a hook returns when it wants to hand feedback back to the model. */
const withContext = (event: string) => ({
  continue: true,
  hookSpecificOutput: {
    hookEventName: event,
    additionalContext: 'feedback the model is meant to receive',
  },
});

describe('the guard preserves additionalContext where CC reads it', () => {
  // Documented by the binary. All three were absent from the old allow-list.
  it.each(['Stop', 'SubagentStop', 'PostToolBatch'])(
    'does NOT strip additionalContext on %s',
    (event) => {
      const out = sanitizeOutput(withContext(event), event) as {
        hookSpecificOutput?: { additionalContext?: string; hookEventName?: string };
      };
      expect(out.hookSpecificOutput?.additionalContext).toBe(
        'feedback the model is meant to receive'
      );
      expect(out.hookSpecificOutput?.hookEventName).toBe(event);
    }
  );

  // The events the old list did get right — kept so a fix cannot regress them.
  it.each([
    'UserPromptSubmit',
    'PreToolUse',
    'PostToolUse',
    'PostToolUseFailure',
    'SessionStart',
  ])('still preserves additionalContext on %s', (event) => {
    const out = sanitizeOutput(withContext(event), event) as {
      hookSpecificOutput?: { additionalContext?: string };
    };
    expect(out.hookSpecificOutput?.additionalContext).toBeDefined();
  });
});

describe('the guard still strips where CC does NOT read', () => {
  // #1794: a WorktreeCreate response carrying a UserPromptSubmit envelope made
  // CC create a literal-named directory from the additionalContext string.
  // The guard must keep failing that case, or this fix is just a disable.
  it.each(['CwdChanged', 'FileChanged', 'ConfigChange', 'TaskCreated'])(
    'strips additionalContext on %s',
    (event) => {
      const out = sanitizeOutput(withContext(event), event) as {
        hookSpecificOutput?: { additionalContext?: string };
      };
      expect(out.hookSpecificOutput?.additionalContext).toBeUndefined();
    }
  );

  // Issue #3457 follow-up (2026-08-12): PostCompact was REMOVED from
  // EVENTS_WITH_ADDITIONAL_CONTEXT, not merely left unreviewed — traced
  // against the shipped 2.1.228 binary and found to lack the
  // `hook_additional_context` executor marker every real additionalContext
  // consumer carries (see spec/cc-output-keys.spec.yml). Confirms #3321.
  it('strips additionalContext on PostCompact (settled unsupported, #3321/#3457)', () => {
    const out = sanitizeOutput(withContext('PostCompact'), 'PostCompact') as {
      hookSpecificOutput?: { additionalContext?: string };
    };
    expect(out.hookSpecificOutput?.additionalContext).toBeUndefined();
  });

  it('drops hookSpecificOutput entirely once it is emptied', () => {
    const out = sanitizeOutput(withContext('CwdChanged'), 'CwdChanged') as {
      hookSpecificOutput?: unknown;
      continue?: boolean;
    };
    expect(out.hookSpecificOutput).toBeUndefined();
    expect(out.continue).toBe(true);
  });
});

describe('WorktreeCreate envelope handling', () => {
  // CC's envelope validator hard-requires hookEventName inside every
  // hookSpecificOutput. Stripping just the field while keeping worktreePath
  // emitted `{"hookSpecificOutput":{"worktreePath":...}}` — the exact
  // malformed shape this guard exists to prevent. On an event that does not
  // consume hookSpecificOutput the whole object is dropped instead.
  it('drops hookSpecificOutput entirely on WorktreeCreate', () => {
    const result = {
      continue: true,
      hookSpecificOutput: {
        hookEventName: 'WorktreeCreate',
        worktreePath: '/tmp/wt',
      },
    };
    const out = sanitizeOutput(result, 'WorktreeCreate') as {
      hookSpecificOutput?: { hookEventName?: string; worktreePath?: string };
    };
    expect(out.hookSpecificOutput).toBeUndefined();
    expect(out.continue).toBe(true);
  });
});

describe('never emits hookSpecificOutput without hookEventName', () => {
  // Reproduces the production failure: the stdin-read race (#3415) delivered
  // 0 bytes, hook_event normalized to 'unknown', and the old Rule 1 stripped
  // hookEventName while leaving updatedInput — CC rejected the envelope with
  // "hookSpecificOutput is missing required field hookEventName". Observed
  // verbatim in session transcripts as
  // {"continue":true,"suppressOutput":true,"hookSpecificOutput":{"updatedInput":{"command":"","timeout":120000}}}.
  it('drops the whole envelope when the hook ran on an empty payload (stdin race)', () => {
    const result = {
      continue: true,
      suppressOutput: true,
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        updatedInput: { command: '', timeout: 120000 },
      },
    };
    const out = sanitizeOutput(result, 'unknown', true) as {
      hookSpecificOutput?: unknown;
      continue?: boolean;
    };
    expect(out.hookSpecificOutput).toBeUndefined();
    expect(out.continue).toBe(true);
  });

  // 'unknown' means the payload lacked the event field — not that the firing
  // event rejects hookSpecificOutput. The security suite fires hooks with
  // real payloads and no hook_event_name; dropping a self-describing deny
  // there turned "expected deny" into "got abstain". CC routes on the
  // declared hookEventName, so a well-formed envelope is emitted intact.
  it('keeps a self-describing envelope when the event is unidentifiable', () => {
    const result = {
      continue: false,
      stopReason: 'denied',
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'deny',
        permissionDecisionReason: 'denied',
      },
    };
    const out = sanitizeOutput(result, 'unknown') as {
      hookSpecificOutput?: { hookEventName?: string; permissionDecision?: string };
      continue?: boolean;
    };
    expect(out.hookSpecificOutput?.hookEventName).toBe('PreToolUse');
    expect(out.hookSpecificOutput?.permissionDecision).toBe('deny');
    expect(out.continue).toBe(false);
  });

  it('drops a garbage-labeled envelope even when the event is unidentifiable', () => {
    const result = {
      continue: true,
      hookSpecificOutput: { hookEventName: 'NotARealEvent', additionalContext: 'x' },
    };
    const out = sanitizeOutput(result, 'unknown') as {
      hookSpecificOutput?: unknown;
    };
    expect(out.hookSpecificOutput).toBeUndefined();
  });

  it('drops a bare envelope on an unknown event (no hookEventName to salvage)', () => {
    const result = {
      continue: true,
      hookSpecificOutput: { updatedInput: { command: 'ls', timeout: 120000 } },
    };
    const out = sanitizeOutput(result, 'unknown') as {
      hookSpecificOutput?: unknown;
    };
    expect(out.hookSpecificOutput).toBeUndefined();
  });

  it('repairs a bare envelope on a consuming event by injecting the firing event', () => {
    const result = {
      continue: true,
      hookSpecificOutput: { additionalContext: 'advisory text' },
    };
    const out = sanitizeOutput(result, 'PreToolUse') as {
      hookSpecificOutput?: { hookEventName?: string; additionalContext?: string };
    };
    expect(out.hookSpecificOutput?.hookEventName).toBe('PreToolUse');
    expect(out.hookSpecificOutput?.additionalContext).toBe('advisory text');
  });

  // Sweep every firing event the guard knows about (plus the unknown/empty
  // cases the stdin race produces) against the canonical result shapes, and
  // assert the invariant directly: any hookSpecificOutput that leaves the
  // guard carries hookEventName.
  it.each([
    ...EVENTS_WITH_HOOK_EVENT_NAME,
    'WorktreeCreate',
    'CwdChanged',
    'Notification',
    'unknown',
    '',
  ])('invariant holds on firing event %s', (event) => {
    const shapes = [
      withContext('PreToolUse'),
      {
        continue: true,
        suppressOutput: true,
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'deny',
          permissionDecisionReason: 'nope',
        },
      },
      {
        continue: true,
        suppressOutput: true,
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          updatedInput: { command: 'git status', timeout: 120000 },
        },
      },
      { continue: true, hookSpecificOutput: { additionalContext: 'bare' } },
      { continue: true, hookSpecificOutput: { updatedInput: { command: 'x' } } },
      { continue: true, hookSpecificOutput: { worktreePath: '/tmp/wt' } },
    ];
    for (const result of shapes) {
      const out = sanitizeOutput(result, event) as {
        hookSpecificOutput?: { hookEventName?: unknown };
      };
      if (out.hookSpecificOutput !== undefined) {
        expect(
          out.hookSpecificOutput.hookEventName,
          `emitted hookSpecificOutput without hookEventName on ${event}: ${JSON.stringify(out)}`
        ).toBeDefined();
      }
    }
  });
});

describe('the generated contract is internally coherent', () => {
  it('every additionalContext event also accepts hookSpecificOutput', () => {
    // CC requires hookEventName inside every hookSpecificOutput. An event that
    // reads additionalContext but is missing from the hookEventName list would
    // be unrepresentable.
    for (const event of EVENTS_WITH_ADDITIONAL_CONTEXT as Set<string>) {
      expect(
        (EVENTS_WITH_HOOK_EVENT_NAME as Set<string>).has(event),
        `${event} reads additionalContext but is absent from EVENTS_WITH_HOOK_EVENT_NAME`
      ).toBe(true);
    }
  });

  it('carries the three events the hand-typed list was missing', () => {
    for (const event of ['Stop', 'SubagentStop', 'PostToolBatch']) {
      expect(
        (EVENTS_WITH_ADDITIONAL_CONTEXT as Set<string>).has(event),
        `${event} is documented by the CC binary and must be allow-listed`
      ).toBe(true);
    }
  });

  it('never strips a key the spec marks UNVERIFIED', () => {
    // Unverified means "we do not know", and stripping on not-knowing is
    // exactly how Stop broke. The guard must leave these alone.
    for (const key of UNVERIFIED_KEYS as Set<string>) {
      const result = {
        continue: true,
        hookSpecificOutput: { hookEventName: 'PreToolUse', [key]: 'value' },
      };
      const out = sanitizeOutput(result, 'PreToolUse') as {
        hookSpecificOutput?: Record<string, unknown>;
      };
      expect(
        out.hookSpecificOutput?.[key],
        `${key} is UNVERIFIED and must not be stripped`
      ).toBe('value');
    }
  });
});
